"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { ShapeMorph } from "@/components/ui/shape";
import { Icon } from "@/components/ui/icon";
import { MotionPresence, MotionSurface } from "@/components/ui/presence";

export const dropzoneVariants = cva("v-drop", {
  variants: { variant: { default: "", compact: "-compact" } },
  defaultVariants: { variant: "default" },
});
export type DropzoneFile = {
  name: string;
  size: number;
  type: string;
  lastModified: number;
};
export type DropzoneRejection = {
  file: File;
  code: "file-type" | "file-size";
  reason: string;
};
export type DropzoneProps = React.ComponentProps<"div"> &
  VariantProps<typeof dropzoneVariants> & {
    onFilesSelected?: (files: File[]) => void;
    onFilesRejected?: (files: DropzoneRejection[]) => void;
    accept?: string;
    /** Maximum bytes per file. Omit to leave file size unrestricted. */
    maxSize?: number;
    multiple?: boolean;
    disabled?: boolean;
    showReceipt?: boolean;
  };
function fileSize(bytes: number) {
  return bytes < 1024
    ? `${bytes} B`
    : bytes < 1024 * 1024
      ? `${Math.round(bytes / 1024)} KB`
      : `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}
function acceptsFile(file: File, accept?: string) {
  if (!accept?.trim()) return true;
  return accept.split(",").some((rule) => {
    const type = rule.trim().toLowerCase();
    return type.startsWith(".")
      ? file.name.toLowerCase().endsWith(type)
      : type.endsWith("/*")
        ? file.type.toLowerCase().startsWith(type.slice(0, -1))
        : file.type.toLowerCase() === type;
  });
}
export function Dropzone({
  className,
  children,
  variant,
  onFilesSelected,
  onFilesRejected,
  accept,
  maxSize,
  multiple = true,
  disabled,
  showReceipt = true,
  onDragEnter,
  onDragOver,
  onDragLeave,
  onDrop,
  onClick,
  onKeyDown,
  "aria-describedby": describedBy,
  ...props
}: DropzoneProps) {
  const picker = React.useRef<HTMLInputElement>(null),
    depth = React.useRef(0);
  const id = React.useId();
  const [over, setOver] = React.useState(false);
  const [selected, setSelected] = React.useState<DropzoneFile[]>([]);
  const [rejections, setRejections] = React.useState<DropzoneRejection[]>([]);
  const receive = (files: File[]) => {
    const chosen = multiple ? files : files.slice(0, 1),
      accepted: File[] = [],
      rejected: DropzoneRejection[] = [];
    for (const file of chosen) {
      if (!acceptsFile(file, accept))
        rejected.push({
          file,
          code: "file-type",
          reason: "This file type is not accepted.",
        });
      else if (
        maxSize !== undefined &&
        Number.isFinite(maxSize) &&
        maxSize >= 0 &&
        file.size > maxSize
      )
        rejected.push({
          file,
          code: "file-size",
          reason: `Choose a file smaller than ${fileSize(maxSize)}.`,
        });
      else accepted.push(file);
    }
    setSelected(
      accepted.map(({ name, size, type, lastModified }) => ({
        name,
        size,
        type,
        lastModified,
      })),
    );
    setRejections(rejected);
    onFilesSelected?.(accepted);
    if (rejected.length) onFilesRejected?.(rejected);
  };
  const state = disabled
    ? "disabled"
    : over
      ? "over"
      : rejections.length
        ? "error"
        : selected.length
          ? "selected"
          : "rest";
  return (
    <div
      data-slot="dropzone"
      data-part="root"
      data-drop=""
      data-state={state}
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || undefined}
      aria-label="Add files"
      aria-describedby={[
        `${id}-help`,
        showReceipt && selected.length ? `${id}-receipt` : null,
        rejections.length ? `${id}-error` : null,
        describedBy,
      ]
        .filter(Boolean)
        .join(" ")}
      className={cn(dropzoneVariants({ variant }), className)}
      onClick={(event) => {
        onClick?.(event);
        if (
          !event.defaultPrevented &&
          !disabled &&
          event.target !== picker.current
        )
          picker.current?.click();
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (
          !event.defaultPrevented &&
          !disabled &&
          (event.key === "Enter" || event.key === " ")
        ) {
          event.preventDefault();
          picker.current?.click();
        }
      }}
      onDragEnter={(event) => {
        onDragEnter?.(event);
        const cancelled = event.defaultPrevented;
        event.preventDefault();
        if (!cancelled && !disabled && ++depth.current > 0) setOver(true);
      }}
      onDragOver={(event) => {
        onDragOver?.(event);
        event.preventDefault();
        event.dataTransfer.dropEffect = disabled ? "none" : "copy";
      }}
      onDragLeave={(event) => {
        onDragLeave?.(event);
        event.preventDefault();
        if (--depth.current <= 0) {
          depth.current = 0;
          setOver(false);
        }
      }}
      onDrop={(event) => {
        onDrop?.(event);
        const cancelled = event.defaultPrevented;
        event.preventDefault();
        depth.current = 0;
        setOver(false);
        if (!cancelled && !disabled)
          receive(Array.from(event.dataTransfer.files));
      }}
      {...props}
    >
      <input
        ref={picker}
        type="file"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        tabIndex={-1}
        className="sr-only"
        aria-hidden="true"
        onChange={(event) => {
          receive(Array.from(event.target.files ?? []));
          event.target.value = "";
        }}
      />
      {children ?? (
        <>
          <span data-slot="dropzone-art" aria-hidden="true">
            <ShapeMorph name="pebble-soft" className="v-drop__pebble" />
            <ShapeMorph name="daisy-12" className="v-drop__flower" />
            <span data-slot="dropzone-symbol">
              <Icon name={selected.length ? "check" : "upload"} />
            </span>
          </span>
          <span data-slot="dropzone-copy">
            <b>
              {over
                ? "Let them land here"
                : selected.length
                  ? "Ready when you are"
                  : "A place for your files"}
            </b>
            <span>
              {over
                ? "Release to add your files"
                : "Drop files here, or choose from your device."}
            </span>
          </span>
          <span data-slot="dropzone-action">
            {selected.length ? "Choose files again" : "Choose files"}
            <Icon name="arrow-up-right" />
          </span>
        </>
      )}
      <span id={`${id}-help`} data-slot="dropzone-help">
        {accept
          ? `Accepts ${accept
              .split(",")
              .map((type) => type.trim())
              .join(", ")}.`
          : "Any file type."}
        {maxSize !== undefined && Number.isFinite(maxSize) && maxSize >= 0
          ? ` Up to ${fileSize(maxSize)} per file.`
          : ""}
        {!multiple ? " One file at a time." : ""}
      </span>
      <MotionPresence>
        {showReceipt && selected.length > 0 && (
          <MotionSurface key="receipt" asChild preset="fade">
            <div
              id={`${id}-receipt`}
              data-slot="dropzone-receipt"
              data-drop-result=""
              role="status"
            >
              <b>
                {selected.length} file{selected.length === 1 ? "" : "s"}{" "}
                selected
              </b>
              {selected.slice(0, 3).map((file, index) => (
                <span data-slot="dropzone-file" key={`${file.name}-${index}`}>
                  <Icon name="file" />
                  <span title={file.name}>{file.name}</span>
                  <small>{fileSize(file.size)}</small>
                </span>
              ))}
              {selected.length > 3 && (
                <small>And {selected.length - 3} more.</small>
              )}
            </div>
          </MotionSurface>
        )}
        {rejections.length > 0 && (
          <MotionSurface key="error" asChild preset="fade">
            <p id={`${id}-error`} data-slot="dropzone-error" role="alert">
              <b>
                {rejections.length === 1
                  ? rejections[0].file.name
                  : `${rejections.length} files`}{" "}
                couldn’t be added.
              </b>{" "}
              {rejections[0].reason}
            </p>
          </MotionSurface>
        )}
      </MotionPresence>
    </div>
  );
}

@layer cojeev-states {
[data-slot="dropzone"] { position:relative; isolation:isolate; display:grid; justify-items:center; gap:14px; width:100%; min-width:0; padding:30px 24px 24px; border:1.5px dashed var(--v-text-2); border-radius:26px 34px 28px 38px; background:var(--v-canvas); color:var(--v-text); text-align:center; cursor:pointer; transition:background var(--t-element),border-color var(--t-element); }
[data-slot="dropzone"]:not([aria-disabled="true"]):hover { background:color-mix(in oklab,var(--v-blue) 8%,var(--v-canvas)); border-color:var(--v-text); }
[data-slot="dropzone"][data-state="over"] { background:color-mix(in oklab,var(--v-blue) 18%,var(--v-canvas)); border:1.5px solid var(--v-text); }
[data-slot="dropzone"][data-state="error"] { border-color:var(--v-danger-ink); }
[data-slot="dropzone"]:focus-visible { outline:2px solid var(--ring); outline-offset:4px; }
[data-slot="dropzone-art"] { position:relative; display:grid; place-items:center; width:104px; height:90px; margin:0 0 4px; }
[data-slot="dropzone-art"] .v-drop__pebble { position:absolute; width:94px; height:94px; color:var(--v-blue); transform:rotate(-18deg); }
[data-slot="dropzone-art"] .v-drop__flower { position:absolute; right:-2px; bottom:-2px; width:38px; height:38px; color:var(--v-yellow); transform:rotate(8deg); }
[data-slot="dropzone-symbol"] { position:relative; display:grid; place-items:center; color:var(--ink-fixed); }
[data-slot="dropzone-symbol"] .v-icon { width:32px; height:32px; stroke-width:1.8; }
[data-slot="dropzone-copy"] { display:grid; gap:6px; max-width:38ch; }
[data-slot="dropzone-copy"] b { font-family:var(--font-display); font-size:22px; font-weight:600; letter-spacing:-.02em; line-height:1.2; }
[data-slot="dropzone-copy"] > span { font-size:14px; color:var(--v-text-2); line-height:1.45; }
[data-slot="dropzone-action"] { display:inline-flex; align-items:center; gap:7px; border-bottom:1px solid currentColor; padding-bottom:2px; font-size:13px; font-weight:600; }
[data-slot="dropzone-action"] .v-icon { width:15px; height:15px; }
[data-slot="dropzone-help"] { max-width:48ch; font-size:12px; line-height:1.5; color:var(--v-text-2); overflow-wrap:anywhere; }
[data-slot="dropzone-receipt"] { display:grid; gap:9px; width:100%; min-width:0; margin-top:2px; padding-top:14px; border-top:1px solid var(--v-border); text-align:start; font-size:13px; }
[data-slot="dropzone-receipt"] > b { font-size:12px; font-weight:600; }
[data-slot="dropzone-file"] { display:grid; grid-template-columns:16px minmax(0,1fr) auto; gap:8px; align-items:start; }
[data-slot="dropzone-file"] .v-icon { width:16px; height:16px; }
[data-slot="dropzone-file"] > span { overflow-wrap:anywhere; line-height:1.4; }
[data-slot="dropzone-file"] small { color:var(--v-text-2); font-size:11px; line-height:1.6; }
[data-slot="dropzone-error"] { width:100%; padding:12px 14px; background:color-mix(in oklab,var(--v-danger-ink) 8%,var(--v-canvas)); border-radius:12px; color:var(--v-danger-ink); font-size:13px; line-height:1.5; text-align:start; overflow-wrap:anywhere; }
[data-slot="dropzone"][aria-disabled="true"] { cursor:not-allowed; color:var(--v-disabled-ink); background:var(--v-disabled-face); border-color:var(--v-disabled-edge); }
[data-slot="dropzone"][aria-disabled="true"] [data-slot="dropzone-art"] { opacity:.5; }
[data-slot="dropzone"].-compact { grid-template-columns:60px minmax(0,1fr); justify-items:start; gap:8px 16px; padding:20px; text-align:start; }
[data-slot="dropzone"].-compact [data-slot="dropzone-art"] { grid-row:1 / 4; width:60px; height:64px; margin:0; }
[data-slot="dropzone"].-compact .v-drop__pebble { width:62px; height:62px; }
[data-slot="dropzone"].-compact .v-drop__flower { width:24px; height:24px; }
[data-slot="dropzone"].-compact [data-slot="dropzone-symbol"] .v-icon { width:24px; height:24px; }
[data-slot="dropzone"].-compact [data-slot="dropzone-copy"] b { font-size:18px; }
[data-slot="dropzone"].-compact :is([data-slot="dropzone-help"],[data-slot="dropzone-receipt"],[data-slot="dropzone-error"]) { grid-column:1 / -1; }
@media(max-width:420px) { [data-slot="dropzone"] { padding:24px 18px 20px; } }
@media(prefers-reduced-motion:reduce) { [data-slot="dropzone"] { transition:none; } }

}
